            const parts = String(rankingStr).split(',');
            for (let i = 0; i < parts.length; i++) {
                const part = parts[i].trim();
                const match = part.match(/(.+):(\d+)分/);
                if (match) {
                    rankings.push({
                        sect: match[1].trim(),
                        score: parseInt(match[2])
