            if (typeof actualData === 'string') {
                if (actualData.trim() === "") {
                    return "暂无";
                }

                const items = actualData.split(',');
                const result = [];

                for (let i = 0; i < items.length; i += 2) {
                    if (i + 1 < items.length) {
                        result.push(`${items[i].trim()}(${items[i + 1].trim()})`);
                    } else {
                        result.push(items[i].trim());
                    }
                }
                return result.join(', ');
            }

            if (Array.isArray(actualData)) {
                if (actualData.length === 0) {
                    return "暂无";
                }

                return actualData.map(item => {
                    if (typeof item === 'string' && item.includes(',')) {
                        const parts = item.split(',');
                        return `${parts[0].trim()}(${parts[1] ? parts[1].trim() : '未知'})`;
                    }
                    return String(item);
                }).join(', ');
            }

            return "暂无";
