    function SafeGetValue(obj, path, defaultValue = "N/A") {
        try {
            let keys = Array.isArray(path) ? path : path.split('.');
            let current = obj;
            for (let i = 0; i < keys.length; i++) {
                if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                    return defaultValue;
                }
                current = current[keys[i]];
            }
            if (current === undefined || current === null) {
                return defaultValue;
            }
            if (Array.isArray(current)) {
                if (current.length > 0) {
                     const actualValue = current[0];
                     if (typeof actualValue === 'boolean') {
                         return actualValue;
                     }
                     return String(actualValue);
                } else {
                     return defaultValue;
                }
            }
            if (typeof current === 'boolean') {
                return current;
            }
            return String(current);
        } catch (error) {
            console.warn('SafeGetValue error:', error);
            return defaultValue;
        }
    }

    function extractCleanValue(rawValue) {
        try {
            if (rawValue === null || rawValue === undefined) {
                return "无";
            }

            if (Array.isArray(rawValue)) {
                if (rawValue.length === 0) {
                    return "无";
                }

                let actualValue = rawValue[0];

                if (typeof actualValue === 'string' && actualValue.includes(',')) {
                    return actualValue.split(',').join(', ');
                }

                if (Array.isArray(actualValue)) {
                    return actualValue.join(', ');
                }

                return String(actualValue);
            }

            return String(rawValue);
        } catch (error) {
            console.warn('extractCleanValue error:', error);
            return String(rawValue || "无");
        }
    }

