                        result.push(`${items[i].trim()}(${items[i + 1].trim()})`);
                    } else {
                        result.push(items[i].trim());
                    }
                }
                return result.join(', ');
            }

            if (Array.isArray(actualData)) {
                if (actualData.length === 0) {
                    return "暂无";
                }

                return actualData.map(item => {
                    if (typeof item === 'string' && item.includes(',')) {
