            { path: 'nested.deep.value', expected: 'found' },
            { path: 'array', expected: 'first' },
            { path: 'nonexistent', expected: 'N/A' },
            { path: 'nested.missing.path', expected: 'N/A' },
            { path: 'nullValue', expected: 'N/A' },
            { path: 'number', expected: '42' }
        ];

        tests.forEach(test => {
            const result = SafeGetValue(testObj, test.path);
            if (result === test.expected) {
                logDebug('function-test', `  ✓ ${test.path} → "${result}"`, 'success');
            } else {
                logDebug('function-test', `  ✗ ${test.path} → "${result}" (expected: "${test.expected}")`, 'error');
            }
        });
    }

    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            if (current.length > 0) {
                const actualValue = current[0];
                if (typeof actualValue === 'boolean') {
                    return actualValue;
                }
                return String(actualValue);
            } else {
                return defaultValue;
            }
        }
        if (typeof current === 'boolean') {
            return current;
        }
        return String(current);
    }

    function dumpRawData() {
        const rawDiv = document.getElementById('raw-data-dump');
        if (!rawDiv) return;

        if (!globalState.dataStructure) {
            rawDiv.textContent = '无可用数据进行转储';
            return;
        }

        try {
            const formatted = JSON.stringify(globalState.dataStructure, null, 2);
            rawDiv.textContent = formatted;
        } catch (error) {
            rawDiv.textContent = `数据转储失败: ${error.message}`;
        }
    }

    async function runFullDiagnostic() {
        globalState.functionErrors = [];

        logDebug('system-check', '🚀 开始完整诊断...');

        const apiWorking = await testChatAPI();

        if (apiWorking) {
            await analyzeDataStructure();
            validateKeyData();
            testUtilityFunctions();
            dumpRawData();
        } else {
            logDebug('data-status', '⚠️ 由于API不可用，跳过后续测试', 'error');
            logDebug('key-data-check', '⚠️ 由于API不可用，跳过数据验证', 'error');
            testUtilityFunctions();
        }

        if (globalState.functionErrors.length === 0) {
            logDebug('system-check', '✅ 所有测试通过！', 'success');
        } else {
            logDebug('system-check', `❌ 发现 ${globalState.functionErrors.length} 个问题`, 'error');
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        logDebug('system-check', '页面加载完成，准备开始诊断...');
        setTimeout(runFullDiagnostic, 500);
    });
</script>
